    for (let j = 0; j < 2; j++) {
      console.assert(result.get(i, j) === expected[i][j], `Result[${i}][${j}] should be ${expected[i][j]}`);
    }
  }

  console.log("✅ Test 9 passed");
} catch (e) {
  console.error("❌ Test 9 failed:", e.message);
}

